const query = $('Dashboard Webhook').first().json.query || {};
const range = query.days !== undefined ? (query.days === 'all' ? 'all' : String(Number(query.days) || 7)) : '7';
const batch_id = typeof query.batch_id === 'string' ? query.batch_id.trim() : '';
const sheetRows = $input.all();

const now = new Date();
let windowStart = null;
if (range !== 'all') {
  const d = Number(range);
  if (!isNaN(d) && d > 0) {
    windowStart = new Date(now.getTime() - d * 24 * 60 * 60 * 1000);
  }
}

const filteredRows = [];
let total_feedback = 0;
const totals = { feedback: 0, complaints: 0, bugs: 0, ideas: 0, praise: 0, angry: 0, avg_score: 0 };
const by_sentiment = { positive: 0, neutral: 0, negative: 0 };
const by_source = { survey: 0, email: 0, google_review: 0, test: 0 };

let score_sum = 0;

for (const item of sheetRows) {
  const row = item.json || item;
  if (!row.id || !row.received_at) continue;

  const rowDate = new Date(row.received_at);
  if (isNaN(rowDate.getTime())) continue;

  if (batch_id && row.batch_id !== batch_id) continue;
  if (windowStart && rowDate < windowStart) continue;

  filteredRows.push(row);
  total_feedback++;

  totals.feedback++;
  if (row.category === 'complaint') totals.complaints++;
  else if (row.category === 'bug') totals.bugs++;
  else if (row.category === 'idea') totals.ideas++;
  else if (row.category === 'praise') totals.praise++;

  const isAngry = row.is_angry === true || String(row.is_angry).toUpperCase() === 'TRUE';
  if (isAngry) totals.angry++;

  if (by_sentiment[row.sentiment] !== undefined) by_sentiment[row.sentiment]++;
  if (by_source[row.source] !== undefined) by_source[row.source]++;

  const sc = Number(row.sentiment_score) || 0;
  score_sum += sc;
}

totals.avg_score = totals.feedback > 0 ? Math.round((score_sum / totals.feedback) * 100) / 100 : 0;

// Top issues ranking (strictly identical to WF4 logic)
const groups = {};
for (const row of filteredRows) {
  if (row.category !== 'complaint' && row.category !== 'bug') continue;
  const groupName = (row.issue_group || '').trim().toLowerCase();
  if (!groupName || groupName === 'untriaged') continue;

  if (!groups[groupName]) {
    groups[groupName] = {
      issue_group: groupName,
      count: 0,
      angry_count: 0,
      score_sum: 0
    };
  }
  groups[groupName].count++;
  const isAngry = row.is_angry === true || String(row.is_angry).toUpperCase() === 'TRUE';
  if (isAngry) groups[groupName].angry_count++;
  const score = Number(row.sentiment_score) || 0;
  groups[groupName].score_sum += score;
}

const groupList = Object.values(groups).map(g => ({
  issue_group: g.issue_group,
  count: g.count,
  angry_count: g.angry_count,
  avg_score: Math.round((g.score_sum / g.count) * 100) / 100
}));

groupList.sort((a, b) => {
  if (b.count !== a.count) return b.count - a.count;
  if (a.avg_score !== b.avg_score) return a.avg_score - b.avg_score;
  return a.issue_group.localeCompare(b.issue_group);
});

const top_issues = groupList.slice(0, 5).map(g => ({
  issue_group: g.issue_group,
  count: g.count,
  angry_count: g.angry_count
}));

// Daily trends (last 30 days max)
const dailyMap = {};
const daysToCover = Math.min(range === 'all' ? 30 : (Number(range) || 7), 30);
for (let i = daysToCover - 1; i >= 0; i--) {
  const d = new Date(now.getTime() - i * 24 * 60 * 60 * 1000);
  const key = d.toISOString().split('T')[0];
  dailyMap[key] = { date: key, count: 0, score_sum: 0, avg_score: 0 };
}

for (const row of filteredRows) {
  const key = String(row.received_at).split('T')[0];
  if (dailyMap[key]) {
    dailyMap[key].count++;
    dailyMap[key].score_sum += Number(row.sentiment_score) || 0;
  }
}

const daily = Object.values(dailyMap).map(d => ({
  date: d.date,
  count: d.count,
  avg_score: d.count > 0 ? Math.round((d.score_sum / d.count) * 100) / 100 : 0
}));

// Recent 20 (newest first, customer_email excluded for privacy)
const sortedRecent = [...filteredRows].sort((a, b) => new Date(b.received_at) - new Date(a.received_at));
const recent = sortedRecent.slice(0, 20).map(r => ({
  received_at: r.received_at,
  source: r.source,
  customer_name: r.customer_name || 'Anonymous',
  rating: r.rating !== '' && r.rating !== null ? Number(r.rating) : 0,
  comment: r.comment,
  category: r.category,
  sentiment: r.sentiment,
  is_angry: r.is_angry === true || String(r.is_angry).toUpperCase() === 'TRUE',
  issue_group: r.issue_group || ''
}));

return [{
  json: {
    ok: true,
    generated_at: now.toISOString(),
    range,
    totals,
    by_sentiment,
    by_source,
    daily,
    top_issues,
    recent
  }
}];
